const SIG=[{"n": "Armadilha do Diabo", "c": "Dois", "alvo": "demônios e ceifeiros", "efeito": "prender", "meio": "giz, tinta, tatuagem ou entalhe", "d": "Símbolo circular desenhado no chão ou no teto que prende um demônio ou ceifeiro que entre nele. Dentro do círculo a entidade perde os poderes e fica indefesa. É quebrado se uma linha do desenho for cortada (água benta, pó, objeto arrastado); exige superfície limpa e atenção."}, {"n": "Pentagrama de Proteção", "c": "Dois (amuleto) / Três (tatuagem)", "alvo": "demônios", "efeito": "impedir possessão", "meio": "amuleto, ou tinta e tatuagem", "d": "Protege contra possessão demoníaca. Imune a possessão por demônios de patente baixa e média; +40 na resistência contra os de alta patente. O amuleto pode ser tirado; a tatuagem não."}, {"n": "Cadeado Demoníaco", "c": "Dois", "alvo": "demônios", "efeito": "impedir abertura de um recipiente", "meio": "desenho em baús, malas e portas", "d": "Impede que um demônio abra algo que o tenha desenhado. A maneira clássica de proteger um objeto que um demônio quer."}, {"n": "Sigilo de Sangue", "c": "Um", "alvo": "anjos", "efeito": "expulsar do local", "meio": "sangue do desenhista", "d": "Desenhado com sangue em parede ou no corpo, expulsa anjos presentes no local. O sinal precisa ser tocado pelo desenhista. Custo físico: sangue tirado de si, dano Leve."}, {"n": "Sigilos Enoquianos", "c": "Três", "alvo": "anjos", "efeito": "impedir entrada e teletransporte", "meio": "tinta ou sangue", "d": "Proteção contra anjos em uma área. Precisam estar em todas as paredes ou entradas; um único sigilo ausente cria uma brecha. Variante de ocultação gravada nas costelas: Complexidade Quatro, com custo de dor e risco."}, {"n": "Sigilo Anti-Possessão", "c": "Dois", "alvo": "possuídos e possuidores", "efeito": "impedir a passagem da soleira", "meio": "pintura na entrada de uma casa", "d": "Distinto do pentagrama. Impede que um possuído atravesse a soleira e que um possuidor entre."}, {"n": "Saquinho de Bruxa", "c": "", "alvo": "moradores da casa", "efeito": "permite à bruxa lançar feitiço à distância", "meio": "ervas, ossos, terra de cemitério", "d": "Pequeno saco deixado na casa de alguém. Buscar um saquinho de bruxa é uma das primeiras ações de um caçador em uma casa assombrada por azar sem explicação."}];
